package pe.andeslink.andestrack.shipment;

import pe.andeslink.andestrack.domain.entity.*;
import pe.andeslink.andestrack.domain.entity.DomainEnums.*;
import pe.andeslink.andestrack.domain.repository.*;
import pe.andeslink.andestrack.realtime.RealtimePublisher;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Optional;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
class TripAndIncidentServiceTest {
    @Test void refusesToStartAnAlreadyStartedTrip(){ViajeRepository trips=mock(ViajeRepository.class);EnvioRepository shipments=mock(EnvioRepository.class);CamionRepository trucks=mock(CamionRepository.class);EventoViajeRepository events=mock(EventoViajeRepository.class);RealtimePublisher realtime=mock(RealtimePublisher.class);Usuario user=new Usuario("Diego Quispe","conductor@andeslink.pe","hash",Rol.DRIVER);Cliente client=new Cliente(new Usuario("María","cliente@andeslink.pe","hash",Rol.CLIENT),"Demo","");Envio shipment=new Envio(client,new Ruta("Lima","Cusco",new BigDecimal("1100.0")),user,"Carga",new BigDecimal("1.0"),BigDecimal.ZERO);Conductor driver=new Conductor(user,"A12345678");Viaje trip=new Viaje(shipment,new Camion("ATL-001","Volvo",new BigDecimal("25.0"),EstadoCamion.ASIGNADO),driver,LocalDateTime.now(),new BigDecimal("55.0"),LocalDateTime.now().plusHours(5));trip.iniciar(LocalDateTime.now());when(trips.findFirstByEnvioIdEnvioAndConductorUsuarioCorreoIgnoreCase(1,user.getCorreo())).thenReturn(Optional.of(trip));TripService service=new TripService(trips,shipments,trucks,events,realtime);ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->service.start("AT-0001",user.getCorreo()));assertEquals(409,ex.getStatusCode().value());verify(trips,never()).save(any());}
    @Test void incidentCreatesAlertAndPublishesControlUpdate(){ViajeRepository trips=mock(ViajeRepository.class);IncidenciaRepository incidents=mock(IncidenciaRepository.class);AlertaRepository alerts=mock(AlertaRepository.class);UsuarioRepository users=mock(UsuarioRepository.class);EventoViajeRepository events=mock(EventoViajeRepository.class);EnvioRepository shipments=mock(EnvioRepository.class);CamionRepository trucks=mock(CamionRepository.class);RealtimePublisher realtime=mock(RealtimePublisher.class);Usuario driverUser=new Usuario("Diego Quispe","conductor@andeslink.pe","hash",Rol.DRIVER);Usuario clientUser=new Usuario("María Paredes","cliente@andeslink.pe","hash",Rol.CLIENT);Cliente client=new Cliente(clientUser,"Demo","999");Ruta route=new Ruta("Lima","Arequipa",new BigDecimal("766.0"));Envio shipment=new Envio(client,route,driverUser,"Carga",new BigDecimal("1.0"),BigDecimal.ZERO);ReflectionTestUtils.setField(shipment,"idEnvio",42);Camion truck=new Camion("ATL-001","Volvo",new BigDecimal("25.0"),EstadoCamion.EN_RUTA);Conductor driver=new Conductor(driverUser,"A12345678");Viaje trip=new Viaje(shipment,truck,driver,LocalDateTime.now().minusHours(1),new BigDecimal("55.0"),LocalDateTime.now().plusHours(4));trip.iniciar(LocalDateTime.now().minusMinutes(30));when(trips.findFirstByEnvioIdEnvioAndConductorUsuarioCorreoIgnoreCase(42,driverUser.getCorreo())).thenReturn(Optional.of(trip));when(incidents.save(any(Incidencia.class))).thenAnswer(i->i.getArgument(0));when(alerts.save(any(Alerta.class))).thenAnswer(i->i.getArgument(0));IncidentService service=new IncidentService(trips,incidents,alerts,users,events,shipments,trucks,realtime);IncidentView result=service.report("AT-0042",driverUser.getCorreo(),new IncidentRequest(TipoIncidencia.TRAFICO_INTENSO,"  Tráfico   intenso  "));assertEquals("Tráfico intenso",result.description());assertFalse(result.resolved());verify(alerts).save(any(Alerta.class));verify(events).save(any(EventoViaje.class));verify(realtime).incidentReported(any(ShipmentView.class),eq(result),any(AlertView.class));}
}